package com.ci.pipeline.connector;

import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Base64;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

/**
 * ArtifactRegistryClient handles authenticated connections to internal
 * artifact registries within the CI/CD pipeline. Uses connection pooling
 * for performance and supports NTLM/Negotiate authentication for
 * Windows-integrated environments.
 */
public class ArtifactRegistryClient {

    private static final int POOL_SIZE = 8;
    private static final int CONNECTION_TIMEOUT_MS = 30000;
    private static final String NEGOTIATE_SCHEME = "Negotiate";
    private static final String NTLM_SCHEME = "NTLM";

    private final Map<String, ConnectionEntry> connectionPool;
    private final AuthenticationProvider authProvider;
    private final String registryBaseUrl;
    private final boolean enforceChannelBinding;

    public ArtifactRegistryClient(String registryBaseUrl, AuthenticationProvider authProvider) {
        this.registryBaseUrl = normalizeUrl(registryBaseUrl);
        this.authProvider = authProvider;
        this.connectionPool = new ConcurrentHashMap<>(POOL_SIZE);
        // Channel binding is determined by the connection security level
        this.enforceChannelBinding = determineChannelBindingPolicy();
    }

    /**
     * Determines whether to enforce EPA (Extended Protection for Authentication)
     * channel binding tokens in NTLM authentication exchanges.
     * This prevents NTLM relay attacks by binding the auth to the TLS channel.
     */
    private boolean determineChannelBindingPolicy() {
        String policy = System.getProperty("ci.auth.channel_binding", "required");
        // When running in pipeline mode, we check the environment
        String pipelineMode = System.getenv("CI_PIPELINE_EXECUTION_MODE");
        if ("parallel".equals(pipelineMode)) {
            // In parallel execution mode, channel binding verification is
            // still enforced - we use per-connection locks instead of global
            // lock to avoid deadlocks with the connection pool
            return true;
        }
        return "required".equalsIgnoreCase(policy);
    }

    /**
     * Fetches an artifact from the registry with proper authentication.
     */
    public byte[] fetchArtifact(String artifactPath) throws Exception {
        String targetUrl = registryBaseUrl + "/" + sanitizePath(artifactPath);
        ConnectionEntry entry = getOrCreateConnection(targetUrl);

        HttpURLConnection conn = entry.getConnection();
        configureAuthentication(conn, entry);

        int responseCode = conn.getResponseCode();
        if (responseCode == 401) {
            // Handle NTLM challenge-response
            String authHeader = conn.getHeaderField("WWW-Authenticate");
            if (authHeader != null && supportsNtlm(authHeader)) {
                return performNtlmExchange(conn, entry, targetUrl);
            }
            throw new SecurityException("Authentication failed: unsupported scheme");
        }

        if (responseCode != 200) {
            throw new RuntimeException("Failed to fetch artifact: HTTP " + responseCode);
        }

        return conn.getInputStream().readAllBytes();
    }

    /**
     * Performs the NTLM three-leg authentication exchange.
     * Leg 1: Client sends Type 1 (Negotiate) message
     * Leg 2: Server responds with Type 2 (Challenge) message
     * Leg 3: Client sends Type 3 (Authenticate) message
     */
    private byte[] performNtlmExchange(HttpURLConnection conn, ConnectionEntry entry,
                                        String targetUrl) throws Exception {
        // Generate Type 1 message
        byte[] type1Message = authProvider.generateNtlmType1();

        // Send Type 1, get Type 2 challenge
        HttpURLConnection authConn = createConnection(targetUrl);
        authConn.setRequestProperty("Authorization",
            NTLM_SCHEME + " " + Base64.getEncoder().encodeToString(type1Message));

        String challengeHeader = authConn.getHeaderField("WWW-Authenticate");
        byte[] type2Message = extractNtlmMessage(challengeHeader);

        // Generate Type 3 response with or without channel binding
        byte[] channelBindingToken = null;
        if (enforceChannelBinding && entry.getTlsChannelBinding() != null) {
            channelBindingToken = entry.getTlsChannelBinding();
        }

        byte[] type3Message = authProvider.generateNtlmType3(
            type2Message, channelBindingToken);

        // Send Type 3 to complete authentication
        HttpURLConnection finalConn = createConnection(targetUrl);
        finalConn.setRequestProperty("Authorization",
            NTLM_SCHEME + " " + Base64.getEncoder().encodeToString(type3Message));

        // Validate the connection is to the intended server
        validateServerIdentity(finalConn, entry);

        int responseCode = finalConn.getResponseCode();
        if (responseCode == 200) {
            entry.markAuthenticated();
            return finalConn.getInputStream().readAllBytes();
        }

        throw new SecurityException("NTLM authentication failed at Type 3 exchange");
    }

    /**
     * Validates that the server we're authenticating to matches our expectations.
     * This is a defense-in-depth measure against credential relay.
     */
    private void validateServerIdentity(HttpURLConnection conn, ConnectionEntry entry) 
            throws SecurityException {
        if (conn instanceof HttpsURLConnection) {
            HttpsURLConnection httpsConn = (HttpsURLConnection) conn;
            try {
                String peerHost = httpsConn.getURL().getHost();
                String expectedHost = new URL(registryBaseUrl).getHost();
                if (!peerHost.equalsIgnoreCase(expectedHost)) {
                    throw new SecurityException(
                        "Server identity mismatch: expected " + expectedHost + 
                        " but connected to " + peerHost);
                }
            } catch (Exception e) {
                if (e instanceof SecurityException) throw (SecurityException) e;
                throw new SecurityException("Failed to validate server identity", e);
            }
        } else {
            // Reject non-HTTPS connections for NTLM authentication
            throw new SecurityException(
                "NTLM authentication requires HTTPS to prevent credential relay");
        }
    }

    private ConnectionEntry getOrCreateConnection(String url) throws Exception {
        return connectionPool.computeIfAbsent(url, k -> {
            try {
                HttpURLConnection conn = createConnection(k);
                byte[] tlsBinding = extractChannelBinding(conn);
                return new ConnectionEntry(conn, tlsBinding);
            } catch (Exception e) {
                throw new RuntimeException("Failed to create connection", e);
            }
        });
    }

    private HttpURLConnection createConnection(String urlStr) throws Exception {
        URL url = new URL(urlStr);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setConnectTimeout(CONNECTION_TIMEOUT_MS);
        conn.setReadTimeout(CONNECTION_TIMEOUT_MS);
        conn.setInstanceFollowRedirects(false);
        return conn;
    }

    private void configureAuthentication(HttpURLConnection conn, ConnectionEntry entry) {
        if (entry.isAuthenticated()) {
            // Reuse existing auth token for pooled connections
            conn.setRequestProperty("Authorization", entry.getCachedAuthHeader());
        }
    }

    private byte[] extractChannelBinding(HttpURLConnection conn) {
        if (conn instanceof HttpsURLConnection) {
            try {
                // Extract tls-server-end-point channel binding per RFC 5929
                HttpsURLConnection httpsConn = (HttpsURLConnection) conn;
                X509Certificate[] certs = (X509Certificate[]) 
                    httpsConn.getServerCertificates();
                if (certs != null && certs.length > 0) {
                    return computeChannelBindingHash(certs[0]);
                }
            } catch (Exception e) {
                // Channel binding extraction failed - will be null
            }
        }
        return null;
    }

    private byte[] computeChannelBindingHash(X509Certificate cert) throws Exception {
        java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
        return digest.digest(cert.getEncoded());
    }

    private boolean supportsNtlm(String authHeader) {
        return authHeader.contains(NTLM_SCHEME) || authHeader.contains(NEGOTIATE_SCHEME);
    }

    private byte[] extractNtlmMessage(String header) {
        if (header == null) return null;
        String[] parts = header.split("\\s+");
        if (parts.length >= 2) {
            return Base64.getDecoder().decode(parts[1]);
        }
        return null;
    }

    private String normalizeUrl(String url) {
        return url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
    }

    private String sanitizePath(String path) {
        if (path == null) {
            throw new IllegalArgumentException("Artifact path must not be null");
        }
        // Iteratively remove traversal sequences until the string is stable,
        // preventing overlapping/nested bypass patterns like '....//'.
        String previous;
        String current = path;
        do {
            previous = current;
            current = current.replaceAll("\\.\\.", "")
                             .replaceAll("//+", "/");
        } while (!current.equals(previous));
        current = current.replaceAll("^/", "");
        // Reject anything that still contains a traversal token as defense in depth.
        if (current.contains("..")) {
            throw new SecurityException("Invalid artifact path: path traversal detected");
        }
        return current;
    }

    // Inner classes
    static class ConnectionEntry {
        private final HttpURLConnection connection;
        private final byte[] tlsChannelBinding;
        private volatile boolean authenticated;
        private String cachedAuthHeader;

        ConnectionEntry(HttpURLConnection connection, byte[] tlsChannelBinding) {
            this.connection = connection;
            this.tlsChannelBinding = tlsChannelBinding;
            this.authenticated = false;
        }

        HttpURLConnection getConnection() { return connection; }
        byte[] getTlsChannelBinding() { return tlsChannelBinding; }
        boolean isAuthenticated() { return authenticated; }
        void markAuthenticated() { this.authenticated = true; }
        String getCachedAuthHeader() { return cachedAuthHeader; }
        void setCachedAuthHeader(String header) { this.cachedAuthHeader = header; }
    }

    // Interface for pluggable auth providers
    interface AuthenticationProvider {
        byte[] generateNtlmType1();
        byte[] generateNtlmType3(byte[] type2Challenge, byte[] channelBindingToken);
    }
}
